const fs = require('fs');

function solve() {
    const buffer = fs.readFileSync(0);
    let offset = 0;

    function nextInt() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        let res = 0;
        while (offset < buffer.length && buffer[offset] > 32) {
            res = res * 10 + (buffer[offset] - 48);
            offset++;
        }
        return res;
    }

    const E = nextInt();
    if (E === null) return;
    const R = nextInt();

    const head = new Int32Array(E + 1).fill(-1);
    const to = new Int32Array(2 * R);
    const weight = new Int32Array(2 * R);
    const nextEdge = new Int32Array(2 * R);
    let edgeCount = 0;

    function addEdge(u, v, w) {
        to[edgeCount] = v;
        weight[edgeCount] = w;
        nextEdge[edgeCount] = head[u];
        head[u] = edgeCount++;

        to[edgeCount] = u;
        weight[edgeCount] = w;
        nextEdge[edgeCount] = head[v];
        head[v] = edgeCount++;
    }

    for (let i = 0; i < R; i++) {
        const u = nextInt();
        const v = nextInt();
        const w = nextInt();
        addEdge(u, v, w);
    }

    // Identificar ciclos usando DFS
    const visited = new Uint8Array(E + 1);
    const parentNode = new Int32Array(E + 1);
    const parentWeight = new Int32Array(E + 1);
    const depth = new Int32Array(E + 1);

    const cycles = [];

    function dfs(u, p, d) {
        visited[u] = 1; // em progresso
        depth[u] = d;

        for (let e = head[u]; e !== -1; e = nextEdge[e]) {
            const v = to[e];
            const w = weight[e];
            if (v === p) continue;

            if (visited[v] === 1) {
                // Ciclo encontrado: aresta de retorno de u para v
                const cycleNodes = [];
                let cycleLen = w;
                let curr = u;
                while (curr !== v) {
                    cycleNodes.push(curr);
                    cycleLen += parentWeight[curr];
                    curr = parentNode[curr];
                }
                cycleNodes.push(v);
                cycles.push({ nodes: cycleNodes, length: cycleLen });
            } else if (visited[v] === 0) {
                parentNode[v] = u;
                parentWeight[v] = w;
                dfs(v, u, d + 1);
            }
        }
        visited[u] = 2; // concluído
    }

    for (let i = 1; i <= E; i++) {
        if (visited[i] === 0) {
            dfs(i, 0, 0);
        }
    }

    // Min-Heap simples para o Dijkstra
    class MinHeap {
        constructor(maxCap) {
            this.nodes = new Int32Array(maxCap);
            this.dists = new Int32Array(maxCap);
            this.size = 0;
