                if (this.dists[p] <= this.dists[i]) break;
                const tn = this.nodes[p];
                const td = this.dists[p];
                this.nodes[p] = this.nodes[i];
                this.dists[p] = this.dists[i];
                this.nodes[i] = tn;
                this.dists[i] = td;
                i = p;
            }
        }

        pop() {
            const resNode = this.nodes[0];
            const resDist = this.dists[0];
            this.size--;
            if (this.size > 0) {
                this.nodes[0] = this.nodes[this.size];
                this.dists[0] = this.dists[this.size];
