                    let left = (i << 1) + 1;
                    let right = left + 1;
                    let smallest = i;
                    if (left < this.size && this.dists[left] < this.dists[smallest]) {
                        smallest = left;
                    }
                    if (right < this.size && this.dists[right] < this.dists[smallest]) {
                        smallest = right;
                    }
                    if (smallest === i) break;
                    const tn = this.nodes[smallest];
                    const td = this.dists[smallest];
                    this.nodes[smallest] = this.nodes[i];
                    this.dists[smallest] = this.dists[i];
                    this.nodes[i] = tn;
                    this.dists[i] = td;
                    i = smallest;
                }
            }
            return { node: resNode, dist: resDist };
        }

        isEmpty() {
            return this.size === 0;
        }

        clear() {
            this.size = 0;
        }
    }

    const heap = new MinHeap(2 * R + E + 10);
    const dist = new Int32Array(E + 1);
    const INF = 1061109567; // 0x3f3f3f3f

    const K = nextInt();
    const results = [];

    for (let q = 0; q < K; q++) {
        const X = nextInt();
        const T = nextInt();

        // Dijkstra a partir de X
        dist.fill(INF);
        dist[X] = 0;
        heap.clear();
        heap.push(X, 0);

        while (!heap.isEmpty()) {
            const { node: u, dist: d } = heap.pop();
            if (d > dist[u]) continue;

            for (let e = head[u]; e !== -1; e = nextEdge[e]) {
                const v = to[e];
                const w = weight[e];
                if (dist[u] + w < dist[v]) {
                    dist[v] = dist[u] + w;
                    heap.push(v, dist[v]);
                }
            }
        }

        let best = Infinity;

        for (let i = 0; i < cycles.length; i++) {
            const cycle = cycles[i];
            if (cycle.length >= T) {
                let minDistToCycle = INF;
                const nodes = cycle.nodes;
                for (let j = 0; j < nodes.length; j++) {
                    const d = dist[nodes[j]];
                    if (d < minDistToCycle) {
                        minDistToCycle = d;
                    }
                }
                if (minDistToCycle < INF) {
                    const cost = 2 * minDistToCycle + cycle.length;
                    if (cost < best) {
                        best = cost;
                    }
                }
            }
        }

        results.push(best === Infinity ? -1 : best);
    }

    console.log(results.join('\n'));
}

